  ],
  "email": {
    "subject": {
      "text": "Your phone, email and website differ across the pages buyers check",
      "cites": ["c2", "c3", "c4"]
    },
    "body": [
      {
        "text": "Your company is described differently on different public pages — a different website, a different phone number, a different office list — depending on which one a buyer opens.",
        "cites": ["c2", "c4", "c7"]
      },
      {
        "text": "The domain behind the email address on your site expires on 2026-12-04 and is not locked against transfer, so a quote or a tender sent to that mailbox can stop arriving.",
        "cites": ["f1"]
      },
      {
        "text": "A tender panel that checks your contractor registration finds a profile with a placeholder phone number and no project record.",
        "cites": ["f9", "c8"]
      }
    ]
  },
  "titles": [
    { "id": "f1", "text": "The domain behind your published email is unlocked and can lapse, taking quotes with it." },
    { "id": "f2", "text": "Anyone can forge email from the address on your site, so a client can be fooled by an invoice." },
    { "id": "f3", "text": "The domain you call canonical can be used to forge supplier or director emails." },
    { "id": "f4", "text": "A Google check flags your robots file as invalid, so directories can outrank your own site." },
    { "id": "f5", "text": "The phone field on your LinkedIn page is broken, so a recruiter or buyer cannot call you." },
    { "id": "f6", "text": "None of your newest Google reviews has an owner reply, so a bad rating sits unanswered." },
    { "id": "f7", "text": "Your enquiry site is missing its security headers, so browsers and scanners flag it to visitors." },
    { "id": "f8", "text": "AI assistants cannot tell who wrote your site or when, so they quote competitors instead." },
    { "id": "f9", "text": "A contractor profile under your registration number shows a placeholder phone and no projects." },
    { "id": "c1", "text": "Your head office unit number differs across three public pages, so a courier can reach the wrong door." },
    { "id": "c2", "text": "Your head office phone differs between sources, so a customer may call a line your site never prints." },
    { "id": "c3", "text": "Your contact email differs between your two site families, so prospects write to two mailboxes." },
    { "id": "c4", "text": "Three websites are presented as yours, so search engines and buyers split your enquiries." },
    { "id": "c5", "text": "An employer profile names a different legal entity, so a candidate or a bank sees another company." },
    { "id": "c6", "text": "Your headcount differs across three public pages, which invites questions in tender and credit checks." },
    { "id": "c7", "text": "Your branch list differs between your site and directories, so a customer cannot find the nearest office." },
    { "id": "c8", "text": "Your contractor grade differs between your site and a directory, so a tender panel sees a weaker record." },
    { "id": "c9", "text": "Your completed project count differs across three pages, which weakens the biggest number you own." },
    { "id": "n1", "text": "A poor rating under a name that matches one of your own engineers is worth checking." },
    { "id": "n2", "text": "Some of your top reviews share one date, which a careful buyer may read as arranged." },
    { "id": "n3", "text": "Your branch number sits one digit from your head office line — worth checking it is not a typo." },
    { "id": "n4", "text": "A directory lists you as small installations only, which may undercut your commercial work." },
    { "id": "n5", "text": "Your calculator's accuracy claim sits against your own site's caveat — worth checking the wording." },
    { "id": "n6", "text": "One site promises a fast installation window and the other a longer one — worth checking which applies." },
    { "id": "n7", "text": "Your mobile site scores well below desktop, which may cost you enquiries from phones." },
    { "id": "n8", "text": "A turnover figure is in circulation from an earlier year, worth checking before a bank sees it." },
    { "id": "n9", "text": "A glowing review carries a name that matches someone on your team — worth checking." },
    { "id": "n10", "text": "Lifetime energy generated is published as two different totals, worth checking which is current." },
    { "id": "n11", "text": "Two tools disagree on whether your robots file is valid, so worth checking which one is right." }
  ],
  "proof": {
    "id": "f1",
    "why": "Anyone can confirm the expiry and lock status of the domain behind your printed email in a minute, and if it lapses the mailbox your quotes come from dies, while every other finding stays exactly as it is."
  }
}

